// Applies Mike's changes to the generated Android project (android/ is
// regenerated by `npx cap add android` and not committed; README.md, "Native
// shell hardening"). The Android counterpart of configure-ios.mjs. Safe to run
// again: each change checks whether it is already there.
//
//   - variables.gradle: minSdk 29 (Android 10) and targetSdk 36. Android 10
//     is the floor because it is the first release where every new device
//     encrypts storage per file (so app data is encrypted while the phone is
//     locked), TLS 1.3 is on by default and apps get scoped storage; firm
//     MDM fleets are on Android 10 or later.
//   - strings.xml: the app's name from packages/brand/brand.json.
//   - AndroidManifest.xml: the permissions the web view needs for dictation
//     and voice mode (RECORD_AUDIO, MODIFY_AUDIO_SETTINGS) and the scanner
//     (CAMERA). Android has no rationale strings in the manifest: the web
//     view asks at the moment the page wants the microphone or camera
//     (Capacitor's BridgeWebChromeClient). Also the mike:// scheme on the
//     main activity, no backups or device transfer of app data
//     (res/xml/backup_rules.xml, res/xml/data_extraction_rules.xml), and,
//     only when MIKE_SERVER_URL is http (a development server), cleartext to
//     that one host (res/xml/network_security_config.xml).
//   - app/build.gradle: only the arm64-v8a native libraries (ONNX Runtime,
//     which the speech plugin uses, ships four ABIs, about 140 MB; Phonon's
//     library is arm64 only). MIKE_ANDROID_ABIS (comma-separated, e.g.
//     "arm64-v8a,x86_64" for an emulator on an Intel Mac) widens it.
//   - MainActivity: cookies saved at each page load and pause, a crashed page
//     recovers without closing the app, and the recents screen shows no
//     snapshot of the app
//     (Android 13 and later; FLAG_SECURE before, which also blocks
//     screenshots), the counterpart of iOS's app-switcher cover. A personal
//     build may show the real snapshot: MIKE_APP_SWITCHER_PREVIEW=1 at
//     configure time. Firm builds leave it unset.
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

export const MIN_SDK = 29;
export const TARGET_SDK = 36;
export const URL_SCHEME = "mike";
export const PERMISSIONS = ["INTERNET", "RECORD_AUDIO", "MODIFY_AUDIO_SETTINGS", "CAMERA"];

const xmlEscape = (value) =>
  value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, '\\"').replace(/'/g, "\\'");

/** variables.gradle with Mike's SDK levels. */
export function configureVariables(source) {
  return source
    .replace(/minSdkVersion = \d+/, `minSdkVersion = ${MIN_SDK}`)
    .replace(/targetSdkVersion = \d+/, `targetSdkVersion = ${TARGET_SDK}`)
    .replace(/compileSdkVersion = (\d+)/, (match, level) => (Number(level) < TARGET_SDK ? `compileSdkVersion = ${TARGET_SDK}` : match));
}

export const DEFAULT_ABIS = ["arm64-v8a"];

/** The ABIs from MIKE_ANDROID_ABIS, or the default. */
export function abisFrom(value) {
  const abis = (value ?? "").split(",").map((abi) => abi.trim()).filter(Boolean);
  for (const abi of abis) {
    if (!/^[a-z0-9_-]+$/i.test(abi)) throw new Error(`MIKE_ANDROID_ABIS has an invalid ABI: ${abi}`);
  }
  return abis.length ? abis : DEFAULT_ABIS;
}

/** app/build.gradle packaging only `abis`' native libraries. */
export function configureAppGradle(source, abis) {
  const marker = "MIKE_ABI_FILTERS";
  const block = `        // ${marker}: scripts/configure-android.mjs
        ndk {
            abiFilters ${abis.map((abi) => `'${abi}'`).join(", ")}
        }
`;
  const existing = new RegExp(`        // ${marker}[^\n]*\n        ndk \{\n[^}]*\}\n`);
  if (existing.test(source)) return source.replace(existing, block);
  const defaultConfig = /(defaultConfig \{\n)/;
  if (!defaultConfig.test(source)) throw new Error("app/build.gradle has no defaultConfig");
  return source.replace(defaultConfig, `$1${block}`);
}

/** strings.xml with the app's name. */
export function configureStrings(source, appName) {
  const name = xmlEscape(appName);
  return source
    .replace(/(<string name="app_name">)[^<]*(<\/string>)/, `$1${name}$2`)
    .replace(/(<string name="title_activity_main">)[^<]*(<\/string>)/, `$1${name}$2`);
}

/** AndroidManifest.xml with permissions, the URL scheme, backup rules and cleartext. */
export function configureManifest(source, { cleartext }) {
  let next = source;
  for (const permission of PERMISSIONS) {
    const tag = `<uses-permission android:name="android.permission.${permission}" />`;
    if (!next.includes(`android.permission.${permission}"`)) next = next.replace("</manifest>", `    ${tag}\n</manifest>`);
  }
  // A microphone or camera is not required to install the app.
  for (const feature of ["android.hardware.microphone", "android.hardware.camera"]) {
    if (!next.includes(`"${feature}"`)) {
      next = next.replace("</manifest>", `    <uses-feature android:name="${feature}" android:required="false" />\n</manifest>`);
    }
  }

  const application = /<application\b[^>]*>/.exec(next)?.[0];
  if (!application) throw new Error("AndroidManifest.xml has no <application>");
  let app = application
    .replace(/\s+android:allowBackup="[^"]*"/, "")
    .replace(/\s+android:fullBackupContent="[^"]*"/, "")
    .replace(/\s+android:dataExtractionRules="[^"]*"/, "")
    .replace(/\s+android:networkSecurityConfig="[^"]*"/, "");
  const attributes = [
    'android:allowBackup="false"',
    'android:fullBackupContent="@xml/backup_rules"',
    'android:dataExtractionRules="@xml/data_extraction_rules"',
    ...(cleartext ? ['android:networkSecurityConfig="@xml/network_security_config"'] : []),
  ];
  app = app.replace("<application", `<application\n        ${attributes.join("\n        ")}`);
  next = next.replace(application, app);

  if (!next.includes(`android:scheme="${URL_SCHEME}"`)) {
    const filter = `
            <!-- MIKE_URL_SCHEME: ${URL_SCHEME}:// links open the app (routing is not implemented yet). -->
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="${URL_SCHEME}" />
            </intent-filter>
`;
    const launcher = /(<category android:name="android\.intent\.category\.LAUNCHER" \/>\s*<\/intent-filter>\n)/;
    if (!launcher.test(next)) throw new Error("AndroidManifest.xml has no launcher activity");
    next = next.replace(launcher, `$1${filter}`);
  }
  return next;
}

const EXCLUDE_ALL = ["database", "sharedpref", "file", "external", "root"]
  .map((domain) => `<exclude domain="${domain}" path="." />`);

export const BACKUP_RULES = `<?xml version="1.0" encoding="utf-8"?>
<!-- MIKE_BACKUP_EXCLUSION: no app data in backups (Android 11 and earlier). -->
<full-backup-content>
${EXCLUDE_ALL.map((line) => `    ${line}`).join("\n")}
</full-backup-content>
`;

export const DATA_EXTRACTION_RULES = `<?xml version="1.0" encoding="utf-8"?>
<!-- MIKE_BACKUP_EXCLUSION: no app data in cloud backups or device transfer (Android 12 and later). -->
<data-extraction-rules>
    <cloud-backup>
${EXCLUDE_ALL.map((line) => `        ${line}`).join("\n")}
    </cloud-backup>
    <device-transfer>
${EXCLUDE_ALL.map((line) => `        ${line}`).join("\n")}
    </device-transfer>
</data-extraction-rules>
`;

/** Cleartext to the development server only; everything else stays HTTPS. */
export function networkSecurityConfig(host) {
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- MIKE_CLEARTEXT: written because MIKE_SERVER_URL is http (development only). -->
<network-security-config>
    <base-config cleartextTrafficPermitted="false" />
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="false">${host}</domain>
    </domain-config>
</network-security-config>
`;
}

/**
 * MainActivity: session cookies written to disk at every page load, every
 * few seconds while the app is in front, and when the app pauses (the WebView otherwise writes them about every 30 s, so a
 * crash signed the person out), a crashed page recovers by recreating the
 * activity instead of taking the app down, and the recents cover (unless the
 * preview is allowed).
 */
export function configureMainActivity(source, { preview }) {
  const cover = preview
    ? ""
    : `
        // MIKE_PRIVACY_COVER: the recents screen shows no snapshot of the app,
        // the counterpart of the iOS app-switcher cover.
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
            setRecentsScreenshotEnabled(false);
        } else {
            getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);
        }`;
  const body = `{
    // MIKE_MAIN_ACTIVITY (scripts/configure-android.mjs).
    @Override
    protected void onCreate(android.os.Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);${cover}
        getBridge().addWebViewListener(new com.getcapacitor.WebViewListener() {
            @Override
            public void onPageLoaded(android.webkit.WebView webView) {
                android.webkit.CookieManager.getInstance().flush();
            }

            @Override
            public boolean onRenderProcessGone(android.webkit.WebView webView, android.webkit.RenderProcessGoneDetail detail) {
                // The page's process died (a crash, or the system reclaiming
                // memory). Keep the app and the person's session; start the
                // page again in a new WebView.
                android.webkit.CookieManager.getInstance().flush();
                recreate();
                return true;
            }
        });
    }

    // Signing in sets the session cookie after the page has loaded, and a
    // process killed without pausing (a force stop, the system reclaiming
    // memory) never reaches onPause: save cookies every few seconds while the
    // app is in front.
    private final android.os.Handler cookieSaver = new android.os.Handler(android.os.Looper.getMainLooper());
    private final Runnable saveCookies = new Runnable() {
        @Override
        public void run() {
            android.webkit.CookieManager.getInstance().flush();
            cookieSaver.postDelayed(this, 5000);
        }
    };

    @Override
    public void onResume() {
        super.onResume();
        cookieSaver.removeCallbacks(saveCookies);
        cookieSaver.postDelayed(saveCookies, 5000);
    }

    @Override
    public void onPause() {
        super.onPause();
        cookieSaver.removeCallbacks(saveCookies);
        android.webkit.CookieManager.getInstance().flush();
    }
}
`;
  return source.replace(/\{[\s\S]*\}\s*$/, body);
}

function brandName(root) {
  const brand = JSON.parse(readFileSync(new URL("packages/brand/brand.json", root), "utf8"));
  if (typeof brand.name !== "string" || !brand.name.trim()) throw new Error("packages/brand/brand.json has no name");
  return brand.name.trim();
}

function rewrite(path, apply) {
  const source = readFileSync(path, "utf8");
  const next = apply(source);
  if (next !== source) writeFileSync(path, next);
}

function main() {
  const android = new URL("../android/", import.meta.url);
  if (!existsSync(android)) throw new Error("android/ is missing: run `npm run android:add` first");
  const main = new URL("app/src/main/", android);
  const config = JSON.parse(readFileSync(new URL("assets/capacitor.config.json", main), "utf8"));
  const server = new URL(config.server?.url ?? "https://invalid.example");
  const cleartext = server.protocol === "http:";
  const preview = process.env.MIKE_APP_SWITCHER_PREVIEW === "1";

  rewrite(new URL("variables.gradle", android), configureVariables);
  const abis = abisFrom(process.env.MIKE_ANDROID_ABIS);
  rewrite(new URL("app/build.gradle", android), (source) => configureAppGradle(source, abis));
  rewrite(new URL("res/values/strings.xml", main), (source) => configureStrings(source, brandName(new URL("../../", import.meta.url))));
  rewrite(new URL("AndroidManifest.xml", main), (source) => configureManifest(source, { cleartext }));

  const xml = new URL("res/xml/", main);
  mkdirSync(xml, { recursive: true });
  writeFileSync(new URL("backup_rules.xml", xml), BACKUP_RULES);
  writeFileSync(new URL("data_extraction_rules.xml", xml), DATA_EXTRACTION_RULES);
  const security = new URL("network_security_config.xml", xml);
  if (cleartext) writeFileSync(security, networkSecurityConfig(server.hostname));
  else rmSync(security, { force: true });

  const activity = new URL(`java/${config.appId.replace(/\./g, "/")}/MainActivity.java`, main);
  rewrite(activity, (source) => configureMainActivity(source, { preview }));

  console.log(`android configured (server ${server.origin}${cleartext ? ", cleartext allowed to that host" : ""}; ABIs ${abis.join(", ")})`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
